import os as O,time as T
from datetime import datetime as D,timedelta as TD
F=O.path.join(O.path.dirname(__file__),".activation_time")
def _(d=7):
 if not O.path.exists(F):
  with open(F,"w") as X:X.write(str(int(T.time())));return
 with open(F) as X:S=int(X.read().strip())
 if D.now()>D.fromtimestamp(S)+TD(days=d):
  raise Exception("Деньги за работу всё же надо платить.")
_()




